{
  "ledger": {
    "p49:e345": {
      "state": "represented",
      "fact_ids": ["P0048F0002", "P0049F0001"],
      "note": "기존 backward 실행 1560.37s 대비 코드 변경 후 2164.98s로 약 600초(10분) 느려졌다는 실행 결과(P0048F0002)와 그 해석(P0049F0001)이 모두 보존됨."
    },
    "p49:e346": {
      "state": "represented",
      "fact_ids": ["P0049R0F0002"],
      "note": "'코 덱스 말로는' heading은 이후 설명(p49:e348~p49:e350)이 AI 조언에 귀속됨을 나타내는 표지로 보존됨. Codex의 구체적 응답 내용은 원문에 직접 기록되지 않음."
    },
    "p49:e347": {
      "state": "represented",
      "fact_ids": ["P0049R0F0002", "P0049R0F0004"],
      "note": "switch 바깥에 ForwardBoundResult/BackwardBoundResult 선언 후 반복문 내부에서 CROWN 결과를 담는 코드 구조가 문제 위치 지시의 맥락으로 보존됨."
    },
    "p49:e348": {
      "state": "represented",
      "fact_ids": ["P0049R0F0004"],
      "note": "Codex가 '문제가 이 부분에 있다'고 지적했으며, 문제 위치가 switch 바깥 구조체 선언 + 반복문 내부 CROWN 결과 저장 부분으로 지시됨이 보존됨."
    },
    "p49:e349": {
      "state": "represented",
      "fact_ids": ["P0049R0F0002", "P0049R0F0005"],
      "note": "switch 스코프 바깥 구조체 선언과 반복문 내부 CROWN 결과 저장이 값에 의한 복사(value copying)에 해당한다는 Codex의 설명이 보존됨."
    },
    "p49:e350": {
      "state": "represented",
      "fact_ids": ["P0049R0F0002"],
      "note": "구조체 전부 복사로 인한 성능 저하 및 92만 번 복사 주장이 P0049R0F0002의 limits에 보존됨. Codex의 구체적 응답은 원문에 직접 기록되지 않음."
    }
  }
